#include <iostream>
#include <iomanip>
#include <cmath>
using namespace std;

int main() {
    int hour, minute;
    char colon;

    while (cin >> hour >> colon >> minute) {
        if (hour == 0 && minute == 0) break;

        double angle = fabs(hour * 30.0 + minute * 0.5 - minute * 6.0);
        angle = min(angle, 360.0 - angle);

        cout << fixed << setprecision(3) << angle << '\n';
    }

    return 0;
}

